import { Component, inject } from '@angular/core';
import {
  FormBuilder,
  FormControl,
  FormGroup,
  ReactiveFormsModule,
  Validators,
} from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import {
  IonButton,
  IonCol,
  IonContent,
  IonGrid,
  IonIcon,
  IonInput,
  IonItem,
  IonLabel,
  IonList,
  IonRow,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { mailOutline } from 'ionicons/icons';
import { getLoginRoutePath, loginEmailRoutePath } from '../../app.routes';
import { AuthService } from '../../common/auth/auth.service';
import { LoadingService } from '../../common/loading/loading.service';
import { LogoComponent } from '../../common/logo/logo.component';

@Component({
  selector: 'app-forgot-password',
  templateUrl: './forgot-password.page.html',
  styleUrls: ['./forgot-password.page.scss'],
  imports: [
    IonContent,
    IonList,
    IonItem,
    IonLabel,
    IonInput,
    IonButton,
    IonGrid,
    IonRow,
    IonCol,
    ReactiveFormsModule,
    RouterLink,
    IonIcon,
    LogoComponent,
  ],
})
export class ForgotPasswordPage {
  form: FormGroup<ForgotPasswordFormControls> = inject(FormBuilder).group({
    email: ['', [Validators.required, Validators.email]],
  });

  readonly loginEmailRouterLink = [getLoginRoutePath(loginEmailRoutePath)];

  private readonly authService = inject(AuthService);
  private readonly loadingService = inject(LoadingService);
  private readonly router = inject(Router);

  constructor() {
    addIcons({ mailOutline });
  }

  async handleForgotPassword(event: any) {
    event.preventDefault();

    this.loadingService.setLoading(true);

    const email = this.form.value.email as string;
    await this.authService.forgotPassword(email);
    await this.router.navigate([getLoginRoutePath()]);

    this.loadingService.setLoading(false);
  }
}

type ForgotPasswordFormControl = FormControl<string | null>;
type ForgotPasswordFormControls = ForgotPasswordForm<ForgotPasswordFormControl>;

interface ForgotPasswordForm<T extends string | FormControl<string | null>> {
  email: T;
}
